Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "title": {
    "text": "Average Gravity by PPG",
    "fontSize": 75,
    "font": "consolas",
    "subtitle": "2024-25 Regular Season | All data available players",
    "subtitleFontSize": 25,
    "subtitleFont": "consolas",
    "subtitleFontWeight": "bold",
    "subtitleColor": "darkslategray"
  },
  "encoding": {
    "y": {
      "field": "AVGGRAVITYSCORE",
      "type": "quantitative",
      "title": "Average Gravity Score",
      "axis": {
        "titleFont": "consolas",
        "labelFont": "consolas",
        "labelFontStyle": "bold",
        "labelFontSize": 20,
        "titleFontSize": 40,
        "titlePadding": 12,
        "labelPadding": 6
      }
    },
    "x": {
      "field": "PTS",
      "type": "quantitative",
      "title": "Points Per Game",
      "axis": {
        "titleFont": "consolas",
        "labelFont": "consolas",
        "labelFontSize": 20,
        "titleFontSize": 40,
        "titlePadding": 12,
        "labelPadding": 6
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "rule",
        "color": "#6B7280",
        "strokeWidth": 2,
        "strokeDash": [
          8,
          6
        ],
        "opacity": 0.8
      },
      "encoding": {
        "x": {
          "aggregate": "mean",
          "field": "PTS",
          "type": "quantitative"
        },
        "y": null,
        "tooltip": [
          {
            "aggregate": "mean",
            "field": "PTS",
            "type": "quantitative",
            "title": "Mean Points Per Game",
            "format": ".2f"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "#6B7280",
        "strokeWidth": 2,
        "strokeDash": [
          8,
          6
        ],
        "opacity": 0.8
      },
      "encoding": {
        "y": {
          "aggregate": "mean",
          "field": "AVGGRAVITYSCORE",
          "type": "quantitative"
        },
        "x": null,
        "tooltip": [
          {
            "aggregate": "mean",
            "field": "AVGGRAVITYSCORE",
            "type": "quantitative",
            "title": "Mean Gravity Score",
            "format": ".2f"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "circle",
        "fill": "black",
        "opacity": 0.2
      },
      "encoding": {
        "size": {
          "condition": {
            "test": "datum.special === ''special''",
            "value": 320
          },
          "value": 160
        },
        "xOffset": {
          "value": -1
        },
        "yOffset": {
          "value": 0.5
        },
        "opacity": {
          "condition": {
            "test": "datum.special === ''special''",
            "value": 0.1
          },
          "value": 0.2
        }
      }
    },
    {
      "mark": {
        "type": "circle",
        "stroke": "white",
        "strokeWidth": 1,
        "color": ""
      },
      "encoding": {
        "tooltip": [
          {
            "field": "name",
            "type": "nominal",
            "title": "Player"
          },
          {
            "field": "PTS",
            "type": "quantitative",
            "title": "Points Per Game"
          },
          {
            "field": "AVGGRAVITYSCORE",
            "type": "quantitative",
            "title": "Average Gravity"
          }
        ],
        "size": {
          "condition": {
            "test": "datum.special === ''special''",
            "value": 200
          },
          "value": 100
        },
        "fill": {
          "condition": {
            "test": "datum.special === ''special''",
            "value": "#0059b3"
          },
          "value": "dodgerblue"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.special === ''special''"
        }
      ],
      "mark": {
        "type": "text",
        "font": "consolas",
        "fontWeight": "bold",
        "align": "left",
        "baseline": "bottom",
        "dx": 7,
        "dy": -1,
        "fontSize": 18
      },
      "encoding": {
        "text": {
          "field": "name",
          "type": "nominal"
        }
      }
    }
  ]
}'
